package br.radio.zapdmr;
import java.nio.*;import java.nio.file.*;import java.util.*;
public final class VoxJniCheck {
 public static void main(String[] args)throws Exception{if(!WebRtcVad.available())throw new AssertionError("JNI VAD unavailable");byte[] bytes=Files.readAllBytes(Paths.get(args[0]));ByteBuffer data=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);List<short[]> frames=new ArrayList<>();for(int n=0;n<100;n++)frames.add(new short[160]);while(data.remaining()>=320){short[] f=new short[160];for(int i=0;i<160;i++)f[i]=data.getShort();frames.add(f);}for(int n=0;n<150;n++)frames.add(new short[160]);CarVoxGate gate=new CarVoxGate(1,800);int starts=0,ends=0;boolean tx=false;WebRtcVad vad=new WebRtcVad(3);long now=1000;try{for(short[] f:frames){CarVoxGate.Result result=gate.frame(vad.speech(f),CarVoxGate.db(f),CarVoxGate.zcr(f),true,tx,now);if(result==CarVoxGate.Result.START){tx=true;starts++;vad.close();vad=new WebRtcVad(3);}if(result==CarVoxGate.Result.END){tx=false;ends++;}if(result==CarVoxGate.Result.UNSAFE)throw new AssertionError(gate.reason());now+=20;}}finally{vad.close();}if(starts<1||ends<1||tx)throw new AssertionError("Voice/silence transition failed: "+starts+"/"+ends);System.out.println("PASS real host JNI WebRTC + CarVoxGate: reference PCM voice starts "+starts+" TX decision(s), silence ends "+ends+"; radio/microphone not used.");}
}
